import Player from "./player";
import Enemy from "./enemy";
import Background from "./background";

const title = document.getElementById("title");
const start = document.getElementById("start");
const audio = document.getElementById("bg-music");
const hearts = new Image();
hearts.src = 'assets/game/UI/hearts.png'

const MUSIC = {
  introBGMusic: './assets/music/bg/memory.mp3',
  medBGMusic: 'assets/music/bg/TemplePath.mp3',
  fastBGMusic: './assets/music/bg/mountainoftrials.mp3',
  gameOverBGMusic: './assets/music/bg/churchofsaints.mp3',
  enemyDestroyAudio: new Audio('./assets/music/effects/destroy2.wav'),
  gameOverAudio: new Audio('./assets/music/effects/game_over.mp3'),
  mistakeAudio: new Audio('assets/music/effects/mistake.wav')
};

MUSIC.enemyDestroyAudio.volume = 0.1;
MUSIC.gameOverAudio.volume = 0.3;
MUSIC.mistakeAudio.volume = 0.2;

const HEARTS = {
  HEART_SIZE: 32,
  HEART_1_X: 0,
  HEART_2_X: 0,
  HEART_3_X: 0,
  HEART_4_X: 0,
  HEART_5_X: 0,
  HEARTS_Y: 0,
  HEARTS_POS_X: 40,
  HEARTS_POS_Y: 27,
  HEART_CANVAS_SIZE: 64
};

export default class TypeBit {
  constructor(canvas) {
    this.ctx = canvas.getContext("2d");
    this.dimensions = {
      width: canvas.width,
      height: canvas.height
    };
    this.bg = new Background(this.ctx);
    this.player = new Player(this.dimensions);
    this.lastTime = 0;
    this.enemiesData = {
      enemies: [],
      enemyWords: [],
      enemyWordPos: []
    }
    this.numEnemies = 1;
    this.maxEnemies = 3;
    this.enemyFrameDuration = 1/8;  // 8 fps enemy animation (initial)
    this.score = 0;
    this.typed = "";
    this.running = false;
    this.level = {
      med: false,
      hard: false
    }
  }

  run() {
    this.running = false;
    audio.src = MUSIC.introBGMusic;
    this.animate(0);
  }

  play() {
    this.running = true;
    this.typed = "";
    title.innerHTML = ""
    start.innerHTML = ""
    this.enemyInterval = setInterval(this.addEnemies.bind(this), 500)
  }

  restart() {
    this.running = false;

    // Reset enemies
    Object.keys(this.enemiesData).forEach(key => this.enemiesData[key] = []);
    this.maxEnemies = 3;
    this.numEnemies = 1;
    this.enemyFrameDuration = 1/8;
    clearInterval(this.enemyInterval);

    // Reset player
    this.typed = "";
    this.score = 0;
    this.player.health = 50;
    this.player.frameDuration = 1/8;
    this.player.frameTimer = 0;
    this.player.frame = 0;
    this.player.hurts = false;
    this.player.walk();
    HEARTS.HEART_1_X = 0;
    HEARTS.HEART_2_X = 0;
    HEARTS.HEART_3_X = 0;
    HEARTS.HEART_4_X = 0;
    HEARTS.HEART_5_X = 0;

    // Reset background and sound
    this.bg.changeSpeed(120);
    audio.src = MUSIC.introBGMusic;
    Object.keys(this.level).forEach(lvl => this.level[lvl] = false);
    title.innerHTML = "typebit"
    start.innerHTML = "press any key to start"
  }

  gameOver() {
    return this.player.outOfHealth();
  }

  changeDifficulty() {
    if (this.score > 50 && this.score <= 100) {
      this.maxEnemies = 3;  this.numEnemies = 2;
      this.bg.changeSpeed(150);
      this.player.frameDuration = 1/10;
      this.enemyFrameDuration   = 1/10;
    } else if (this.score > 100 && this.score <= 150) {
      this.maxEnemies = 4;  this.numEnemies = 2;
      this.bg.changeSpeed(180);
      this.player.frameDuration = 1/12;
      this.enemyFrameDuration   = 1/12;
    } else if (this.score > 150 && this.score <= 200) {
      this.maxEnemies = 5;  this.numEnemies = 3;
      this.bg.changeSpeed(210);
      this.player.frameDuration = 1/12;
      this.enemyFrameDuration   = 1/15;
      if (!this.level.med) {
        audio.src = MUSIC.medBGMusic;
        this.level.med = true;
      }
    } else if (this.score > 200 && this.score <= 250) {
      this.maxEnemies = 5;  this.numEnemies = 3;
      this.bg.changeSpeed(225);
      this.player.frameDuration = 1/15;
      this.enemyFrameDuration   = 1/15;
    } else if (this.score > 250 && this.score <= 350) {
      this.maxEnemies = 6;  this.numEnemies = 4;
      this.bg.changeSpeed(240);
      this.player.frameDuration = 1/20;
      this.enemyFrameDuration   = 1/20;
      if (!this.level.hard) {
        audio.src = MUSIC.fastBGMusic;
        this.player.run();
        this.level.hard = true;
      }
    } else if (this.score > 350 && this.score <= 400) {
      this.maxEnemies = 8;  this.numEnemies = 4;
      this.bg.changeSpeed(300);
      this.player.frameDuration = 1/25;
      this.enemyFrameDuration   = 1/25;
    } else if (this.score > 400 && this.score <= 800) {
      this.maxEnemies = 9;  this.numEnemies = 5;
      this.bg.changeSpeed(300);
      this.player.frameDuration = 1/28;
      this.enemyFrameDuration   = 1/28;
    } else if (this.score > 800) {
      this.maxEnemies = 10; this.numEnemies = 6;
      this.bg.changeSpeed(300);
      this.player.frameDuration = 1/30;
      this.enemyFrameDuration   = 1/30;
    }

    this.enemiesData.enemies.forEach(e => e.frameDuration = this.enemyFrameDuration);
  }

  removeEnemy(enemy) {
    const idx = this.enemiesData.enemies.indexOf(enemy);
    if (idx === -1) return;
    this.enemiesData.enemies.splice(idx, 1);
    this.enemiesData.enemyWords.splice(idx, 1);
    this.enemiesData.enemyWordPos.splice(idx, 1);
  }

  animate(timeStamp) {
    // Cap deltaTime to 50ms to prevent a spiral of death after tab focus loss
    const deltaTime = Math.min((timeStamp - this.lastTime) / 1000, 0.05);
    this.lastTime = timeStamp;

    this.ctx.clearRect(0, 0, this.dimensions.width, this.dimensions.height);
    this.bg.update(deltaTime);
    this.bg.draw();
    this.player.update(deltaTime);
    this.player.draw(this.ctx);

    /* Game over sequence */
    if (this.gameOver() && this.running) {
      audio.src = MUSIC.gameOverBGMusic;
      if (!audio.muted) MUSIC.gameOverAudio.play();
      this.health(this.ctx);
      this.player.dead();
      this.bg.changeSpeed(0);
      title.innerHTML = "GAME OVER";
      start.innerHTML = `final score: ${this.score} <br>[ctrl] to restart`;
      clearInterval(this.enemyInterval);
      this.running = false;
    }

    if (this.running) {
      this.changeDifficulty();
      this.health(this.ctx);
      this.wordSubmit();

      const toRemove = new Set();
      this.enemiesData.enemies.forEach(enemy => {
        enemy.update(deltaTime);
        enemy.draw(this.ctx);

        if (enemy.bounds().right < 0) {
          toRemove.add(enemy);
        } else if (this.player.collidesWith(this.player.bounds(), enemy.bounds())) {
          this.player.hurt();
          toRemove.add(enemy);
        }
      });
      toRemove.forEach(enemy => this.removeEnemy(enemy));

      this.status(this.ctx);
    }

    this.animReq = requestAnimationFrame(this.animate.bind(this));
  }

  status(ctx) {
    ctx.font = "40px VT323";
    ctx.fillText(`score: ${this.score}`, 960, 70)
    ctx.font = "64px VT323";
    ctx.fillText(this.typed, 200, 280)
  }

  addEnemies() {
    for (let i = 0; i < this.numEnemies; i++) {
      if (this.enemiesData.enemies.length < this.maxEnemies) {
        const speed = Math.random();
        const pos = i + Math.random();
        const newEnemy = new Enemy(
          this.dimensions, speed, pos,
          this.enemiesData.enemyWords, this.enemiesData.enemyWordPos
        );
        newEnemy.frameDuration = this.enemyFrameDuration;
        this.enemiesData.enemies.push(newEnemy);
        this.enemiesData.enemyWords.push(newEnemy.words);
        this.enemiesData.enemyWordPos.push(newEnemy.words_y);
      }
    }
  }

  wordSubmit() {
    if (this.typed.slice(-1) === "~") {
      const typedWord = this.typed.slice(0, -1);

      if (this.enemiesData.enemyWords.includes(typedWord)) {
        if (!audio.muted) MUSIC.enemyDestroyAudio.play();
        const idx = this.enemiesData.enemyWords.indexOf(typedWord);
        const enemy = this.enemiesData.enemies[idx];
        this.score += enemy.score;
        this.removeEnemy(enemy);
      } else {
        if (!audio.muted) MUSIC.mistakeAudio.play();
      }

      this.typed = "";
    }
  }

  health(ctx) {
    if (this.player.health < 10) HEARTS.HEART_1_X = 64
    ctx.drawImage(hearts,
      HEARTS.HEART_1_X, HEARTS.HEARTS_Y,
      HEARTS.HEART_SIZE, HEARTS.HEART_SIZE,
      HEARTS.HEARTS_POS_X, HEARTS.HEARTS_POS_Y,
      HEARTS.HEART_CANVAS_SIZE, HEARTS.HEART_CANVAS_SIZE)

    if (this.player.health < 20) HEARTS.HEART_2_X = 64
    ctx.drawImage(hearts,
      HEARTS.HEART_2_X, HEARTS.HEARTS_Y,
      HEARTS.HEART_SIZE, HEARTS.HEART_SIZE,
      HEARTS.HEARTS_POS_X + HEARTS.HEART_CANVAS_SIZE, HEARTS.HEARTS_POS_Y,
      HEARTS.HEART_CANVAS_SIZE, HEARTS.HEART_CANVAS_SIZE)

    if (this.player.health < 30) HEARTS.HEART_3_X = 64
    ctx.drawImage(hearts,
      HEARTS.HEART_3_X, HEARTS.HEARTS_Y,
      HEARTS.HEART_SIZE, HEARTS.HEART_SIZE,
      HEARTS.HEARTS_POS_X + (HEARTS.HEART_CANVAS_SIZE * 2), HEARTS.HEARTS_POS_Y,
      HEARTS.HEART_CANVAS_SIZE, HEARTS.HEART_CANVAS_SIZE)

    if (this.player.health < 40) HEARTS.HEART_4_X = 64
    ctx.drawImage(hearts,
      HEARTS.HEART_4_X, HEARTS.HEARTS_Y,
      HEARTS.HEART_SIZE, HEARTS.HEART_SIZE,
      HEARTS.HEARTS_POS_X + (HEARTS.HEART_CANVAS_SIZE * 3), HEARTS.HEARTS_POS_Y,
      HEARTS.HEART_CANVAS_SIZE, HEARTS.HEART_CANVAS_SIZE)

    if (this.player.health < 50) HEARTS.HEART_5_X = 64
    ctx.drawImage(hearts,
      HEARTS.HEART_5_X, HEARTS.HEARTS_Y,
      HEARTS.HEART_SIZE, HEARTS.HEART_SIZE,
      HEARTS.HEARTS_POS_X + (HEARTS.HEART_CANVAS_SIZE * 4), HEARTS.HEARTS_POS_Y,
      HEARTS.HEART_CANVAS_SIZE, HEARTS.HEART_CANVAS_SIZE)
  }
}
